        DB::table('failure_analyses')->insert(json_decode('[{"item_id": "FAR-2026-001", "tanggal": "2026-09-02", "equip_no": "DZ-007", "component_name": "TRANSMISSION TORQFLOW", "chronology": "Saat operasi dozing overburden, unit DZ-007 tidak dapat bergerak maju/mundur. Tekanan torqflow terukur di bawah standar 17 kg/cm² yaitu hanya 9 kg/cm². Unit dinyatakan breakdown dan WO-001 dibuka.", "five_why_json": "{\"w1\":\"Unit tidak dapat bergerak karena torqflow tidak membangun tekanan.\",\"w2\":\"Pressure control valve torqflow macet dan tidak berfungsi.\",\"w3\":\"Kontaminasi metal debris pada circuit oli transmisi menyebabkan valve seret.\",\"w4\":\"Filter transmisi tidak diganti sesuai jadwal interval 250H karena stok kosong.\",\"root_cause\":\"Manajemen stok filter transmisi tidak terpantau; minimun stok tidak dijaga sehingga PM tidak bisa dilaksanakan tepat waktu.\"}", "fishbone_json": "{\"man\":\"PMC tidak memonitor ketersediaan sparepart filter transmisi sebelum jadwal PM.\",\"machine\":\"Torqflow DZ-007 usia pakai 11.840 jam - komponen sudah mendekati batas lifetime.\",\"material\":\"Kualitas oli transmisi tidak dicek sejak 500 jam terakhir.\",\"method\":\"Prosedur monitoring tekanan torqflow tidak ada dalam form P2H harian.\",\"environment\":\"Unit beroperasi di area berdebu tinggi yang mempercepat kontaminasi oli.\"}", "corrective_action": "Bersihkan circuit transmisi, ganti filter dan oli transmisi, setting ulang pressure control valve.", "preventive_action": "Tambahkan item cek tekanan torqflow pada form P2H harian. Pastikan stok filter transmisi minimum 3 PC selalu tersedia di gudang.", "status": "IN PROGRESS", "lead_investigator": "Hariadi", "created_at": "2026-09-13 08:00:00", "updated_at": "2026-09-13 08:00:00"}, {"item_id": "FAR-2026-002", "tanggal": "2026-09-03", "equip_no": "WL-019", "component_name": "MAIN HYDRAULIC PUMP", "chronology": "Gerakan bucket WL-019 terasa lambat dan tekanan hidrolik rendah di bawah 250 bar dari standar 320 bar. Pressure test menunjukkan main pump mengalami internal leakage.", "five_why_json": "{\"w1\":\"Tekanan hidrolik rendah menyebabkan gerakan bucket lambat dan tidak bertenaga.\",\"w2\":\"Main hydraulic pump mengalami internal leakage dan tidak dapat membangun pressure.\",\"w3\":\"Piston pump aus akibat kontaminasi partikel besi pada oli hidrolik.\",\"w4\":\"Filter return line hidrolik tidak diganti pada PM 500H terakhir.\",\"root_cause\":\"Prosedur PM 500H WL-019 tidak lengkap; penggantian filter return line terlewat menyebabkan kontaminasi oli dan kerusakan pump.\"}", "fishbone_json": "{\"man\":\"Mekanik melewatkan item penggantian filter return line saat PM 500H.\",\"machine\":\"Main pump WL-019 usia pakai 3.950 jam - komponen dalam periode rawan kerusakan.\",\"material\":\"Oli hidrolik terkontaminasi partikel besi dari keausan komponen.\",\"method\":\"Checklist PM 500H tidak mencantumkan verifikasi kondisi oli dengan analisis.\",\"environment\":\"Unit beroperasi di area loading berbatu yang mempercepat getaran komponen.\"}", "corrective_action": "Overhaul main hydraulic pump, ganti seal kit dan piston set, flush system hidrolik, ganti oli dan semua filter.", "preventive_action": "Tambahkan oil analysis hidrolik pada PM 500H. Buat checklist verifikasi tekanan pompa setelah setiap PM.", "status": "IN PROGRESS", "lead_investigator": "Andi Herwan", "created_at": "2026-09-13 08:00:00", "updated_at": "2026-09-13 08:00:00"}, {"item_id": "FAR-2026-003", "tanggal": "2026-09-06", "equip_no": "GST-003", "component_name": "ALTERNATOR", "chronology": "Genset GST-003 mati total saat operasi malam hari karena tegangan drop dari 28V ke 18V. Alternator ditemukan gosong pada rotor coil.", "five_why_json": "{\"w1\":\"Genset mati karena alternator tidak mengisi baterai sehingga tegangan drop.\",\"w2\":\"Rotor coil alternator short circuit dan terbakar.\",\"w3\":\"Suhu internal alternator overheat akibat debu batubara menyumbat ventilasi.\",\"w4\":\"Blowing debu pada housing alternator tidak dilakukan saat servis PM.\",\"root_cause\":\"Prosedur cleaning alternator belum masuk checklist mandatory servis PM 500H genset.\"}", "fishbone_json": "{\"man\":\"Mekanik tidak melakukan blowing debu pada kompartemen alternator saat PM.\",\"machine\":\"Alternator GST-003 usia pakai 4.920 jam tanpa penggantian.\",\"material\":\"Rotor coil kualitas standar rentan terhadap kontaminasi debu batubara.\",\"method\":\"Checklist PM genset tidak mencantumkan cleaning alternator secara spesifik.\",\"environment\":\"Lokasi genset di area stockpile berdebu tebal 24 jam.\"}", "corrective_action": "Ganti alternator baru P/N VG1500090065. Periksa wiring harness dan koneksi charging.", "preventive_action": "Tambahkan item mandatory Blowing & Cleaning Alternator pada checklist PM genset. Lakukan inspeksi visual alternator setiap 250 jam.", "status": "CLOSED", "lead_investigator": "Hariadi", "created_at": "2026-09-13 08:00:00", "updated_at": "2026-09-13 08:00:00"}]', true));

